function refreshPhone(phone){const id=phone?.dataset.screen||state.page;if(phone?.isConnected){const body=phone.querySelector('.phone-body');const scroll=body.scrollTop;body.innerHTML=content(id);body.scrollTop=scroll;hydrateFields();}else render();}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.mode){state.mode=button.dataset.mode;render();return;}if(button.dataset.page){navigate(button.dataset.page);return;}if(button.dataset.action){handleAction(button.dataset.action,button.closest('.phone'),button);}});
document.addEventListener('input',event=>{const el=event.target,phone=el.closest('.phone');if(!phone)return;if(phone.dataset.screen==='write'&&el.name)state.draft[el.name]=el.value;if(el.id==='story-preview')state.draft.preview=el.value;if(el.id==='withdraw-amount'){state.withdrawAmount=el.value;const amount=Number(el.value);phone.querySelector('#withdraw-gross').textContent=phone.querySelector('#withdraw-net').textContent=Number.isFinite(amount)?`$${amount.toFixed(2)}`:'—';}if(el.id==='global-search'){state.query=el.value;phone.querySelector('#search-results').innerHTML=searchResults();}});
document.addEventListener('change',event=>{const el=event.target,phone=el.closest('.phone');if(!phone)return;if(phone.dataset.screen==='write'&&el.name)state.draft[el.name]=el.value;if(el.name==='price'){state.price=el.value;refreshPhone(phone);}if(el.id==='cover-upload'&&el.files.length){if(!['image/jpeg','image/png'].includes(el.files[0].type)||el.files[0].size>10*1024*1024){toast('Choose a JPG or PNG under 10 MB.',phone);return;}state.draft.cover=true;state.draft.coverUrl=URL.createObjectURL(el.files[0]);navigate('write');document.querySelector('.upload-cover img').src=state.draft.coverUrl;}});
document.addEventListener('keydown',event=>{const modal=document.querySelector('.modal-shade');if(!modal)return;if(event.key==='Escape'){dismissSheet(modal.closest('.phone'));}if(event.key==='Tab'){const fields=[...modal.querySelectorAll('button,input,textarea,select,a[href]')].filter(el=>!el.disabled);const first=fields[0],last=fields[fields.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
if(location.hash&&pages.some(p=>p.id===location.hash.slice(1))){state.page=location.hash.slice(1);state.mode='focus';}
render();
